    node.entries[k].key = cbor("json")
    node.entries[k].value = cbor(x.json.get)
    inc k
  node.entries[k].key = cbor("method")
  node.entries[k].value = cbor(x.`method`)
  inc k
  node.entries[k].key = cbor("op")
  node.entries[k].value = cbor("call")
  inc k
  node.entries[k].key = cbor("provider")
